{
  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        normalized_gain = gain / pred_tokens
        accepted = call['parseable'] and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(call['call_id'])
        diagnostics.append({
            'accepted': accepted,
            'call_id': call['call_id'],
            'normalized_gain': round(normalized_gain, 8)
        })
    return {'accepted_call_ids': accepted_call_ids, 'diagnostics': diagnostics}"
}
